using UnityEngine;
public class UsefulMath:MonoBehaviour{public Transform debugCube,fallingCube,targetCube;public float distanceToFallingCube,angleToFallingCube;public Vector3 directionToFallingCube;Vector3 fallingCubeStartPosition;void Start(){if(fallingCube)fallingCubeStartPosition=fallingCube.position;}void Update(){if(!debugCube||!fallingCube)return;distanceToFallingCube=Vector3.Distance(debugCube.position,fallingCube.position);directionToFallingCube=(fallingCube.position-debugCube.position).normalized;angleToFallingCube=Vector3.Angle(debugCube.forward,directionToFallingCube);if(targetCube)targetCube.LookAt(fallingCube);}void OnDrawGizmos(){if(!debugCube||!fallingCube||!targetCube)return;Gizmos.color=Color.green;Gizmos.DrawRay(debugCube.position,debugCube.forward*2f);Gizmos.color=Color.blue;Gizmos.DrawLine(fallingCubeStartPosition,fallingCube.position);Gizmos.color=Color.red;Gizmos.DrawLine(fallingCube.position,targetCube.position);}}
